import math


def calc_number_of_outgoing_chunks_for_swim(header_size: int, body_size: int, chunk_size: int) -> int:
    """A helper that calculates required number of chunks in SWIM compatibility
    mode.

    SWIM does not have JSI protocol implemented in a layered way and it
    assumes, that each chunk contains JSONRPC header, so it needs to know, what
    the size of the header is, and the size is 4 bytes in length. SWIM can
    properly handle only first JSI chunk and only if it really contains JSONRPC
    header (that is always true for FDSW API), but JSI was designed to handle
    any binary message, not only JSONRPC.

    As a result, starting from second frame it is required to prefix it with
    additional 4 zeroed bytes and that additional bytes extend the size of a
    chunk. That makes it quite complex to calculate necessary number of
    chunks to transfer given binary payload.

    This helper calculates required number of chunks needed to transfer message
    composed of *header_size* bytes plus *body_size* bytes, assuming that
    *chunk_size* is the maximal chunk size.

    .. note::
        This function is a subject for removal once SWIM will get renewed,
        layered JSI implementation.

    :param header_size:
        The size of the header part.

    :param body_size:
        The size of the body part.

    :param chunk_size:
        Maximum size of a single chunk, in bytes.

        There also is a minimum size, which is 5 bytes (4 bytes for header, 1
        byte for data).
    """
    total_size = 4 + header_size + body_size  # len(HEADER_SIZE) + len(HEADER) + len(BODY)
    min_chunk_size = 4 + header_size + 1  # Need at least 1 byte in each chunk to transfer BODY part
    if chunk_size < min_chunk_size:
        raise ValueError(f"invalid value for 'chunk_size': must be >= {min_chunk_size}")
    if chunk_size >= total_size:
        return 1  # Always 1 chunk if whole message fits in
    chunk_data_capacity = chunk_size - (4 + header_size)  # Each chunk is prefixed with redundant "header", so only remaining space is left for BODY
    remaining_bytes = body_size - chunk_data_capacity  # Remaining BODY bytes to be sent starting from 2nd frame
    return 1 + math.ceil(remaining_bytes / chunk_data_capacity)
